async function fontCommand(sock, from, msg, q) {
    if (!q) return sock.sendMessage(from, { text: "❌ Please provide text to style!\nExample: .font Hello World" }, { quoted: msg });
    
    const fontNames = Object.keys(fonts);
    let response = "*ITACHI-UCHIHA TEXT FONTS*\n\n";
    
    // Show first 20 fonts by default, or all if requested
    const showAll = q.includes('--all');
    const textToStyle = q.replace('--all', '').trim();
    
    if (showAll) {
        for (let i = 0; i < fontNames.length; i++) {
            response += `${i + 1}. ${fonts[fontNames[i]](textToStyle)}\n`;
            if (i % 50 === 0 && i !== 0) {
                await sock.sendMessage(from, { text: response }, { quoted: msg });
                response = "";
            }
        }
    } else {
        for (let i = 0; i < Math.min(fontNames.length, 30); i++) {
            response += `*${i + 1}:* ${fonts[fontNames[i]](textToStyle)}\n`;
        }
        response += "\n_Use .font [text] --all to see all 100+ styles!_";
    }
    
    if (response) {
        await sock.sendMessage(from, { text: response }, { quoted: msg });
    }
}

module.exports = fontCommand;
